<?php

// The sprite is generated by web/scripts/build-public-assets.mjs and committed. A glyph that is only in the sprite is gone
// after the next run of the script, and the icon component then points at a symbol that does not exist: an empty icon.
it('has the same Phosphor glyphs in the generator, the checked-in sprite and the icon component', function () {
    $generator = (string) file_get_contents(base_path('scripts/build-public-assets.mjs'));
    $sprite = (string) file_get_contents(resource_path('views/components/icons/phosphor-sprite.blade.php'));
    $icon = (string) file_get_contents(resource_path('views/components/public/icon.blade.php'));

    preg_match('/const GLYPHS = \[(.*?)\];/s', $generator, $list);
    preg_match_all("/'([a-z-]+)'/", $list[1] ?? '', $glyphs);
    preg_match_all('/<symbol id="ph-([a-z-]+)"/', $sprite, $symbols);
    preg_match('/\$phosphor = \[(.*?)\];/s', $icon, $known);
    preg_match_all("/'([a-z-]+)'/", $known[1] ?? '', $names);

    expect($glyphs[1])->not->toBeEmpty()
        ->and($symbols[1])->toBe($glyphs[1])
        ->and($names[1])->toBe($glyphs[1]);
});
